impl Speech for BeepClient {
    async fn transcribe(&self, mut audio: mpsc::Receiver<Vec<u8>>, heard: HeardSink) {
        let opened = async {
            let client = self.client().await?;
            let request = Transcribe {
                sample_rate: TRANSCRIBE_RATE,
            };
            timed(CALL_TIMEOUT, "transcription", client.duplex(&request)).await
        };
        let (mut uplink, mut replies) = match opened.await {
            Ok(opened) => opened,
            Err(e) => return heard.hear(Hearing::Failed(e.to_string())).await,
        };
        let up = async move {
            while let Some(pcm) = audio.recv().await {
                if let Err(e) = uplink.send(&ByteBuf::from(pcm)).await {
                    log::debug!("live audio stopped going up: {e}");
                    return;
                }
            }
            if let Err(e) = uplink.finish() {
                log::debug!("ending live audio: {e}");
            }
        };
        tokio::pin!(up);
        let mut up_done = false;
        loop {
            tokio::select! {
                () = &mut up, if !up_done => up_done = true,
                reply = replies.next() => match reply {
                    Ok(Some(Transcription::Delta { text })) => heard.hear(Hearing::Words(text)).await,
                    Ok(Some(Transcription::Done { .. }) | None) => return,
                    Ok(Some(Transcription::Unavailable {})) => {
                        return heard.hear(Hearing::Unavailable).await;
                    }
                    Err(e) => return heard.hear(Hearing::Failed(BeepError::from(e).to_string())).await,
                },
            }
        }
    }

    async fn say(&self, text: String) -> Result<Vec<u8>, BeepError> {
        Ok(self.call(Say { text }).await?.audio.data)
    }

    async fn filler(&self, filler: Filler, said: String) -> Result<Spoken, BeepError> {
        let note = self
            .call(FillerLine {
                step: filler.step,
                said,
                still: filler.still,
            })
            .await?;
        Ok(Spoken {
            text: note.text,
            audio: note.audio.data,
        })
    }
}

#[derive(uniffi::Object)]
pub struct EventStream(AsyncMutex<Replies<Event>>);

impl EventStream {
    fn new(replies: Replies<Event>) -> Arc<Self> {
        Arc::new(Self(AsyncMutex::new(replies)))
    }
}

#[uniffi::export(async_runtime = "tokio")]
impl EventStream {
    /// Next event, `null` once the stream ends.
    pub async fn next(&self) -> Result<Option<Event>, BeepError> {
        Ok(self.0.lock().await.next().await?)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn list_cache_round_trips_and_forgets_what_it_cannot_read() {
        let cache = ListCache {
            models: Some(Models {
                choices: Vec::new(),
                selected: "model-a".into(),
                thinking: ReasoningLevel::Medium,
                auto: false,
                auto_available: false,
            }),
            ..ListCache::default()
        };
        let decoded = decode_list_cache(encode_list_cache(cache));
        assert_eq!(
            decoded.models.map(|m| m.selected).as_deref(),
            Some("model-a")
        );
        assert!(decoded.memories.is_none());
        assert!(decode_list_cache(vec![0xc1]).models.is_none());
    }

    #[test]
    fn history_cache_round_trips_and_forgets_what_it_cannot_read() {
        let cache = HistoryCache {
            updated_at: 42,
            entries: vec![HistoryEntry::Scheduled {
                label: "Morning".into(),
                timestamp: 7,
            }],
            images: Vec::new(),
            files: Vec::new(),
        };
        let decoded = decode_history_cache(encode_history_cache(cache)).expect("it was just saved");
        assert_eq!(decoded.updated_at, 42);
        assert_eq!(decoded.entries.len(), 1);
        assert!(decode_history_cache(vec![0xc1]).is_none());
    }

    #[test]
    fn history_cache_from_before_files_still_reads() {
        let entries: Vec<HistoryEntry> = Vec::new();
        let images: Vec<SentImages> = Vec::new();
        let old = rmp_serde::to_vec(&(42i64, entries, images)).expect("plain values encode");
        let decoded = decode_history_cache(old).expect("an older cache still reads");
        assert_eq!(decoded.updated_at, 42);
        assert!(decoded.files.is_empty());
    }

    fn runtime() -> tokio::runtime::Runtime {
        tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("a test runtime builds")
    }

    fn scratch(name: &str) -> String {
        let dir = std::env::temp_dir().join(format!("beep-bridge-{}-{name}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).expect("the temp dir is writable");
        dir.join("file").to_string_lossy().into_owned()
    }

    #[test]
    fn a_failed_download_leaves_no_partial_file() {
        let path = scratch("failed");
        let result = runtime().block_on(download(&path, |offset| async move {
            if offset == 0 {
                Ok(FilePart {
                    data: vec![1; 4],
                    size: 8,
                })
            } else {
                Err(BeepError::Connection {
                    reason: "dropped".into(),
                })
            }
        }));
        assert!(matches!(result, Err(BeepError::Connection { .. })));
        assert!(files_beside(&path).is_empty());
    }

    #[test]
    fn a_download_lands_whole() {
        let path = scratch("whole");
        let size = runtime().block_on(download(&path, |offset| async move {
            Ok(FilePart {
                data: vec![offset as u8; 4],
                size: 8,
            })
        }));
        assert_eq!(size.expect("the download succeeds"), 8);
        assert_eq!(
            std::fs::read(&path).expect("the file landed"),
            [0, 0, 0, 0, 4, 4, 4, 4]
        );
        assert_eq!(files_beside(&path), ["file"]);
    }

    #[test]
    fn a_pdf_name_stays_in_its_folder() {
        assert_eq!(
            file_name("Solid-state batteries.pdf"),
            "Solid-state batteries.pdf"
        );
        assert_eq!(file_name("../../etc/passwd"), "passwd");
        assert_eq!(file_name(".."), "Research.pdf");
        assert_eq!(file_name(""), "Research.pdf");
    }

    /// The names of the files in `path`'s folder.
    fn files_beside(path: &str) -> Vec<String> {
        let dir = Path::new(path).parent().expect("the file is in a folder");
        std::fs::read_dir(dir)
            .expect("the folder is readable")
            .map(|entry| {
                let entry = entry.expect("the folder is readable");
                entry.file_name().to_string_lossy().into_owned()
            })
            .collect()
    }
}
